Local Ltac transport_chunks segs m a bs ::= transport_chunks_n8 segs m a bs; try transport_cond_ro segs m a bs.
Local Ltac addr_diff E A ::=
  lazymatch A with
  | E => constr:(0%Z)
  | _ =>
    match E with
    | Z.add ?X ?c1 =>
        let c1 := zlit c1 in
        lazymatch A with
        | Z.add X ?c2 => let c2 := zlit c2 in eval vm_compute in (c1 - c2)%Z
        | X => c1
        | _ => let e := zlit E in let a := zlit A in eval vm_compute in (e - a)%Z
        end
    | _ =>
        lazymatch A with
        | Z.add E ?c2 => let c2 := zlit c2 in eval vm_compute in (- c2)%Z
        | _ => let e := zlit E in let a := zlit A in eval vm_compute in (e - a)%Z
        end
    end
  end.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Import ListNotations.
Open Scope bv_scope.
Open Scope Z_scope.
Section HCW.
  Context {HCEIL : HeapCeil}.
  Ltac step1 ::= step1_hex.

  (* [comment removed for export] *)
  Ltac u8_leaf :=
    lazymatch goal with FR : rw_cells _ _ (bv_unsigned ?sp + -16) _, ST : stk _ _ _ (bv_unsigned _ + -16) |- _ =>
      release_frame FR ST (bv_unsigned sp) end;
    run_to ([] : list Z);
    lazymatch goal with |- context [ret_pc (Z_to_bv 64 ?raz)] =>
      replace (ret_pc (Z_to_bv 64 raz)) with (Z_to_bv 64 raz) by (symmetry; apply ret_pc_even; assumption) end;
    apply evt_done; unhide_post; cbv beta;
    lazymatch goal with |- context [MS ?R _ _ _ None ?mm _ = _] => let rr := rv_of R in
      lazymatch goal with TB : rw_cells _ mm (_ + 32 + _) [C1 ?a; C1 ?b; C1 ?c; C1 ?d] |- _ => exists rr, mm, a, b, c, d end end;
    split; [reflexivity|]; rv_cbv;
    repeat (split; [first [assumption | reflexivity] |]);
    lazymatch goal with |- _ /\ _ => split; [| assumption] end;
    lazymatch goal with |- context [u8len ?cp] =>
      first [ rewrite (u8len_1 cp) by assumption
            | rewrite (u8len_2 cp) by assumption
            | rewrite (u8len_3 cp) by first [assumption | lia]
            | rewrite (u8len_4 cp) by first [assumption | lia] ] end;
    assumption.
  (* [comment removed for export] *)
  Ltac explore_u8 stops :=
    run_to stops;
    lazymatch goal with
    | |- evt _ _ (MS _ _ (Z_to_bv 64 ?pc) _ _ _ _) =>
        lazymatch stops with
        | context [pc] => u8_leaf
        | _ => idtac "=== STUCK at" pc; print_leaf
        end
    | |- evt _ _ (MS _ _ (if _ then _ else _) _ _ _ _) =>
        let K := fresh "K" in if_cases K; zify_cond K; try rewrite !unsigned_zb in K; box_ugly K;
        [ prune_or K ltac:(explore_u8 stops) | prune_or K ltac:(explore_u8 stops) ]
    end.

  Lemma u8leaf : u8leaf_stmt.
